import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  color,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new THREE.Group();
  group.name = 'hub-collection-card-2';

  const cardW = 2.1;
  const cardH = 2.5;

  // --- Engineered gradient surface (backdrop of the card) ---
  const gradGeo = new THREE.PlaneGeometry(cardW, cardH, 1, 1);
  const gradMat = new MeshStandardNodeMaterial({
    roughness: 0.58,
    metalness: 0.32,
    clearcoat: 0.15,
    transparent: true,
  });

  const topColor = color(colors.surface);
  const botColor = color(colors.ink);
  const gradT = smoothstep(-cardH / 2, cardH / 2, positionLocal.y);

  // subtle grain via hashed noise
  const grain = fract(
    sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.035);

  gradMat.colorNode = mix(botColor, topColor, gradT).add(grain);
  gradMat.opacityNode = undefined;

  const gradMesh = new THREE.Mesh(gradGeo, gradMat);
  gradMesh.position.set(0, 0, 0);
  group.add(gradMesh);

  // --- Decorative orb image, layered in front of the gradient ---
  const imgW = cardW * 0.86;
  const imgH = cardH * 0.86;
  const imgGeo = new THREE.PlaneGeometry(imgW, imgH, 1, 1);
  const imgMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.15,
    transparent: true,
    depthWrite: false,
  });
  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0, 0.02);
  group.add(imgMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  // --- Rim light: accent-hued highlight, kept node-local and capped ---
  const rimLight = new THREE.PointLight(new THREE.Color(colors.accent), 0.9, 6);
  rimLight.position.set(-1.4, 0.6, 1.6);
  group.add(rimLight);

  // group scene placement (position applied by adapter already handles scenePosition,
  // but rotation/scale are safe to set explicitly per spec)
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // --- Weighted-settle entrance (static composition, no interactivity) ---
  group.scale.setScalar(0.96);
  gradMat.opacity = 0;
  imgMat.opacity = 0;

  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    [gradMat, imgMat],
    {
      opacity: 1,
      duration: 0.7,
      ease: 'power2.out',
    },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(gradMat);
    gsap.killTweensOf(imgMat);

    group.remove(rimLight);

    gradGeo.dispose();
    gradMat.dispose();
    imgGeo.dispose();
    if (imgMat.map) imgMat.map.dispose();
    imgMat.dispose();
  };

  return group;
}
